// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // initial owner is address(0); only the owner may call transferOwnership
        vm.prank(address(0));
        try c.transferOwnership(newOwner) {
            assertTrue(c.owner() == newOwner, "owner must equal supplied newOwner");
        } catch {
            assertTrue(false, "owner transfer must succeed for current owner");
        }
    }
}

